<div class="page-head"><div><div class="page-kicker">Administration</div><h1 class="page-title">Users & access</h1><p class="page-subtitle">Assign capabilities per person instead of creating a role for every combination.</p></div><div class="head-actions"><a class="btn primary" href="<?=site_url('users/create')?>">+ Add user</a></div></div>
<div class="card"><div class="toolbar"><form class="search" method="get"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="6"/><path d="m16 16 5 5"/></svg><input name="q" value="<?=esc($q??'')?>" placeholder="Search name, username or email…"></form><div class="pill-row"><span class="pill"><?=number_format(count($users))?> accounts</span></div></div><div class="table-wrap"><table class="table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last login</th><th>Actions</th></tr></thead><tbody><?php if(!$users): ?><tr><td colspan="5"><div class="empty"><strong>No users found</strong>Create the first staff account to get started.</div></td></tr><?php else: foreach($users as $user): ?><tr><td><div class="split" style="justify-content:flex-start"><div class="avatar" style="background:var(--primary-soft);color:var(--primary)"><?=esc(strtoupper(substr($user['name'],0,1)))?></div><div><strong><?=esc($user['name'])?></strong><div class="muted">@<?=esc($user['username'])?><?=!empty($user['email'])?' · '.esc($user['email']):''?></div></div></div></td><td><span class="badge primary"><?=esc(ucwords(str_replace('_',' ',$user['role'])))?></span></td><td><span class="badge <?=$user['status']?'success':'neutral'?>"><?=$user['status']?'Active':'Disabled'?></span></td><td><?=esc($user['last_login']??'Never')?></td><td class="table-actions"><a class="btn small" href="<?=site_url('users/'.$user['id'].'/edit')?>">Edit access</a><?php if((int)$user['status']===1&&(int)$user['id']!==(int)session()->get('user_id')):?><form method="post" action="<?=site_url('users/'.$user['id'].'/delete')?>" onsubmit="return confirm('Deactivate this account?')"><?=csrf_field()?><button class="btn small ghost" type="submit">Deactivate</button></form><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
